{"title": "Requests", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Requests",
    "subtitle": "Handled by the API per interval",
    "anchor": "start",
    "color": "#1d2433",
    "subtitleColor": "#5b6475"
  },
  "data": {
    "url": {
      "index": "app-logs-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "must": [
              "%dashboard_context-must_clause%",
              {
                "range": {
                  "timestamp": {
                    "%timefilter%": true
                  }
                }
              },
              {
                "match_phrase": {
                  "app.message": "Request handled"
                }
              }
            ],
            "must_not": [
              "%dashboard_context-must_not_clause%"
            ],
            "filter": [
              "%dashboard_context-filter_clause%"
            ]
          }
        },
        "aggs": {
          "time": {
            "date_histogram": {
              "field": "timestamp",
              "interval": {
                "%autointerval%": true
              },
              "min_doc_count": 0,
              "extended_bounds": {
                "min": {
                  "%timefilter%": "min"
                },
                "max": {
                  "%timefilter%": "max"
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.time.buckets"
    }
  },
  "mark": {
    "type": "line",
    "strokeWidth": 2,
    "color": "#2a78d6",
    "point": {
      "size": 30,
      "filled": true,
      "color": "#2a78d6"
    }
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "doc_count",
      "type": "quantitative",
      "title": "requests"
    },
    "tooltip": [
      {
        "field": "key",
        "type": "temporal",
        "title": "time",
        "format": "%H:%M:%S"
      },
      {
        "field": "doc_count",
        "title": "requests"
      }
    ]
  },
  "config": {
    "axis": {
      "labelColor": "#5b6475",
      "titleColor": "#5b6475",
      "gridColor": "#e6e9ef",
      "domainColor": "#d5dae3"
    },
    "view": {
      "stroke": null
    }
  }
}"}}

{"title": "Latency (p95)", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Latency (p95)",
    "subtitle": "95% of requests answered within",
    "anchor": "start",
    "color": "#1d2433",
    "subtitleColor": "#5b6475"
  },
  "data": {
    "url": {
      "index": "app-logs-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "must": [
              "%dashboard_context-must_clause%",
              {
                "range": {
                  "timestamp": {
                    "%timefilter%": true
                  }
                }
              },
              {
                "match_phrase": {
                  "app.message": "Request handled"
                }
              }
            ],
            "must_not": [
              "%dashboard_context-must_not_clause%"
            ],
            "filter": [
              "%dashboard_context-filter_clause%"
            ]
          }
        },
        "aggs": {
          "time": {
            "date_histogram": {
              "field": "timestamp",
              "interval": {
                "%autointerval%": true
              },
              "min_doc_count": 0,
              "extended_bounds": {
                "min": {
                  "%timefilter%": "min"
                },
                "max": {
                  "%timefilter%": "max"
                }
              }
            },
            "aggs": {
              "latency": {
                "percentiles": {
                  "field": "app.context.duration_ms",
                  "percents": [
                    95
                  ]
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.time.buckets"
    }
  },
  "mark": {
    "type": "line",
    "strokeWidth": 2,
    "color": "#2a78d6",
    "point": {
      "size": 30,
      "filled": true,
      "color": "#2a78d6"
    }
  },
  "encoding": {
    "x": {
      "field": "key",
      "type": "temporal",
      "title": null
    },
    "y": {
      "field": "p95",
      "type": "quantitative",
      "title": "milliseconds"
    },
    "tooltip": [
      {
        "field": "key",
        "type": "temporal",
        "title": "time",
        "format": "%H:%M:%S"
      },
      {
        "field": "p95",
        "title": "p95 ms",
        "format": ".0f"
      }
    ]
  },
  "config": {
    "axis": {
      "labelColor": "#5b6475",
      "titleColor": "#5b6475",
      "gridColor": "#e6e9ef",
      "domainColor": "#d5dae3"
    },
    "view": {
      "stroke": null
    }
  },
  "transform": [
    {
      "calculate": "datum.latency.values['95.0']",
      "as": "p95"
    }
  ]
}"}}

