{"title": "Commands", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "title": {
    "text": "Commands",
    "subtitle": "Handled and refused, such as checkouts without stock",
    "anchor": "start",
    "color": "#1d2433",
    "subtitleColor": "#5b6475"
  },
  "data": {
    "url": {
      "index": "app-logs-*",
      "body": {
        "size": 0,
        "query": {
          "bool": {
            "must": [
              "%dashboard_context-must_clause%",
              {
                "range": {
                  "timestamp": {
                    "%timefilter%": true
                  }
                }
              },
              {
                "bool": {
                  "should": [
                    {
                      "match_phrase": {
                        "app.message": "Command handled"
                      }
                    },
                    {
                      "match_phrase": {
                        "app.message": "Command failed"
                      }
                    }
                  ]
                }
              }
            ],
            "must_not": [
              "%dashboard_context-must_not_clause%"
            ],
            "filter": [
              "%dashboard_context-filter_clause%"
            ]
          }
        },
        "aggs": {
          "commands": {
            "terms": {
              "field": "app.context.command.keyword",
              "size": 10
            },
            "aggs": {
              "outcomes": {
                "terms": {
                  "field": "app.message.keyword",
                  "size": 2
                }
              }
            }
          }
        }
      }
    },
    "format": {
      "property": "aggregations.commands.buckets"
    }
  },
  "mark": {
    "type": "bar",
    "cornerRadiusEnd": 4
  },
  "encoding": {
    "y": {
      "field": "command",
      "type": "nominal",
      "title": null,
      "sort": "-x"
    },
    "x": {
      "field": "count",
      "type": "quantitative",
      "title": "commands",
      "stack": "zero"
    },
    "color": {
      "field": "outcome",
      "type": "nominal",
      "title": null,
      "scale": {
        "domain": [
          "Command handled",
          "Command failed"
        ],
        "range": [
          "#2a78d6",
          "#eb6834"
        ]
      }
    },
    "tooltip": [
      {
        "field": "command"
      },
      {
        "field": "outcome"
      },
      {
        "field": "count"
      }
    ]
  },
  "config": {
    "axis": {
      "labelColor": "#5b6475",
      "titleColor": "#5b6475",
      "gridColor": "#e6e9ef",
      "domainColor": "#d5dae3"
    },
    "view": {
      "stroke": null
    }
  },
  "transform": [
    {
      "flatten": [
        "outcomes.buckets"
      ],
      "as": [
        "outcome_bucket"
      ]
    },
    {
      "calculate": "replace(datum.key, /^.*\\\\/, '')",
      "as": "command"
    },
    {
      "calculate": "datum.outcome_bucket.key",
      "as": "outcome"
    },
    {
      "calculate": "datum.outcome_bucket.doc_count",
      "as": "count"
    }
  ]
}"}}
